const BASE={"stages": [{"t": "Фундамент", "why": "Как играть, голова без мусора, сон, тело, энергия, еда. Без этого остальное не держится."}, {"t": "Голова", "why": "Ответственность, фокус, тревога, отношение к себе, гормоны."}, {"t": "Люди", "why": "Смелость, речь, границы, окружение."}, {"t": "Дело", "why": "Музыка как дело, работа, образ, деньги, настоящие желания."}], "course": [{"id": "c1", "st": 1, "p": "head", "t": "Как играть в свою жизнь", "why": "Арсен: если бы жизнь подавалась как квесты в игре — без давления, — он бы «играл свою жизнь». Начинаем с того же: не заставлять себя, а договариваться.", "les": ["Внедряется только то, что делаешь в кайф. Через силу через 5–6 недель мозг запишет «это плохо» и начнёт саботировать.", "Метод: месяц понемногу и с удовольствием → проверка → шаг вверх. Не «с понедельника новая жизнь», а маленькие ступеньки.", "Засчитывай победы. Встал, хоть и не хотел, — победа. Всё сверх минимума — «экстра», бонус."], "tasks": [{"t": "3 вечера подряд записать по 3 «я смог»", "how": "Мелочи считаются: встал, вышел, открыл FL. Засчитай на третий вечер."}, {"t": "Договориться с собой: дело, которое не хочется, сделать по-своему", "how": "Тренировка под любимый альбом, отжимания между раундами Brawl Stars, дорога в зал с новым треком."}, {"t": "Неделя «экстра»: всё, что сделал сверх плана, записывать отдельно", "how": "Заметка «Экстра». В воскресенье посчитай, сколько набралось."}], "cards": ["12.0", "12.1", "12.2", "12.3", "12.4", "12.5", "12.23"]}, {"id": "c2", "st": 1, "p": "deals", "t": "Выгрузить голову", "why": "Ты держишь дела в голове. Каждое незакрытое дело висит фоном и жрёт энергию — отсюда «непонятно, с чего начать». Метод Ваагна: сначала всё из головы наружу.", "les": ["Голова — для идей, а не для хранения. Всё, что висит, — во «Входящие» (они на экране «Сегодня»).", "Каждую мысль разбираешь: нужно вообще? Сделаю за 2 минуты — делаю сразу. Нет — ставлю в квест или срок. Не нужно — удаляю.", "Закрыл мелочь — появилась энергия. Её сразу вкладываешь в следующий маленький шаг."], "tasks": [{"t": "Скинуть во «Входящие» всё, что висит в голове — минимум 20 пунктов", "how": "Военкомат, долги, музыка, учёба, вещи, люди, «надо бы». Всё подряд, без сортировки."}, {"t": "Разобрать «Входящие» до нуля", "how": "Каждый пункт: сделать, удалить или превратить в шаг квеста."}, {"t": "Закрыть 3 мелочи по 2 минуты", "how": "Перевести 200 брату, ответить на сообщение, выкинуть мусор со стола."}], "cards": ["2.0", "2.1", "2.2", "2.4", "2.5", "4.0"]}, {"id": "c3", "st": 1, "p": "body", "t": "Сон", "why": "Пока сон сбит, остальное не растёт. Арсен, Ваагн и Лимарев ставят сон первым. Ты ложишься в 12 — нормально, теперь делаем сон глубоким.", "les": ["Норма: упал — не помнишь, как заснул — проснулся бодрым. Разбитость по утрам — не норма.", "Мелатонин делается из дневного серотонина: утром свет в глаза, вечером тёплый свет и без яркого экрана.", "Уснуть — значит остыть: горячий душ за час до сна, потом прохлада. Не ложиться с полным животом."], "tasks": [{"t": "3 утра подряд: 10 минут дневного света в глаза до телефона", "how": "Окно, балкон, улица."}, {"t": "3 вечера подряд: последняя еда за 3 часа до сна", "how": "Вечерние перекусы и пиво — главный враг."}, {"t": "Неделю: за 30 минут до сна — без экрана", "how": "Душ, музыка без экрана, книга, растяжка."}], "cards": ["10.0", "10.1", "10.2", "10.3", "10.4", "10.5", "9.7"]}, {"id": "c4", "st": 1, "p": "body", "t": "Тело в движении", "why": "Гормоны доходят до цели только с кровью и лимфой. Без движения не работает ничего — ни энергия, ни настроение, ни похудение.", "les": ["Минимум в день — 6–10 км ходьбы и 50–100 приседаний.", "Сначала привычка появляться, потом интенсивность. Человек похудел на 68 кг: каждый день ходил в зал на 5 минут.", "Уходи с тренировки на пике, а не «до блевоты» — завтра захочется снова."], "tasks": [{"t": "8 000 шагов за день", "how": "Дорога к Эдуарду пешком тоже считается."}, {"t": "100 приседаний за день в любой разбивке", "how": "По 10–20 между делами или между треками."}, {"t": "Первый поход в зал: просто появиться", "how": "Даже 5 минут засчитываются. Цель — дорога, а не рекорд."}], "cards": ["9.0", "1.18", "12.6", "11.1", "1.19", "12.20"]}, {"id": "c5", "st": 1, "p": "head", "t": "Энергия: чистый день", "why": "Порно и фантазии дают мозгу «победу без усилий» — и обычная жизнь блекнет. Закрыл кран — вернулись воля, фокус и смелость с людьми.", "les": ["Мозг не отличает картинку от жизни: фантазия запускает настоящие гормоны.", "Иллюзию ломает возврат в реальность: вдох → руки → «кто я, где я, что вокруг?» → 20 приседаний.", "Запрет не работает — работает осознанность и энергия в движение: в тело и в музыку."], "tasks": [{"t": "Убрать триггеры: уведомления выключены, провокационные аккаунты скрыты", "how": "Один раз, 15 минут."}, {"t": "Ритуал возврата сработал хотя бы раз", "how": "Отметь, когда сработает."}, {"t": "7 чистых дней (не обязательно подряд)", "how": "Дни не считаем подряд — счётчик сам наводит на мысль «сколько можно». Сорвался — запиши, что спровоцировало."}], "cards": ["8.0", "8.1", "8.2", "8.3", "8.4", "8.7", "8.8", "8.9", "8.10", "12.19"]}, {"id": "c6", "st": 1, "p": "body", "t": "Еда без скуки", "why": "Ты ешь сладкое от скуки после еды. Это не слабость — мозг ищет быстрый дофамин, потому что день пустой. Лечится не запретом, а заменой и движением.", "les": ["Мозг выбирает дело по формуле «награда минус усилия». Сладкое — самая дешёвая награда.", "«Правильное» питание через силу вредит сильнее, чем неидеальное с удовольствием. Не диета, а меньше лишнего.", "Когда тянет — сначала тело: 20 приседаний, вода, выйти из кухни. Через 10 минут желание слабее."], "tasks": [{"t": "3 дня записывать: когда потянуло к сладкому и что было до этого", "how": "Скука? После еды? Перед ноутом?"}, {"t": "Убрать сладкое с видного места дома", "how": "Что не видно — то не хочется."}, {"t": "5 раз за неделю: вместо сладкого — 20 приседаний и вода", "how": "Засчитай на пятый раз."}], "cards": ["8.2", "11.33", "1.5", "9.6", "11.25"]}, {"id": "c7", "st": 2, "p": "head", "t": "Хозяин своей жизни", "why": "Позиция творца: «я это создал — какие выводы?». Военкомат динамит, программа пробная, ноут общий — всё правда. Но вопрос один: что я могу сделать?", "les": ["Две правды: по закону виноват вор, но чтобы не крали — закрывай окна.", "Решение — это шаг, который можно сделать прямо сейчас. «Новая жизнь» — не решение.", "Жалость к себе — низшая форма просьбы. Путь взрослого — сначала сделать, потом просить."], "tasks": [{"t": "Переписать 3 своих жалобы в «что я сделаю»", "how": "«Военкомат динамит» → «звоню каждые 3 дня и записываю, кто что сказал»."}, {"t": "День без «мне не дали / меня динамят» — только «я сделал / я позволил»", "how": "Следи за языком весь день."}, {"t": "Разбор одного срыва по трём вопросам", "how": "Что сделал не так? Что мог лучше? Что сделаю в следующий раз?"}], "cards": ["1.8", "11.0", "11.4", "11.5", "11.24", "7.11", "12.15", "12.13", "1.26"]}, {"id": "c8", "st": 2, "p": "head", "t": "Фокус и стимулы", "why": "Лента, короткие видео и Brawl Stars поднимают планку удовольствия так, что сидеть над треком кажется скучным. Вернуть вкус к делу можно за пару недель.", "les": ["Чем больше на виду лишнего, тем сильнее распыляется внимание. Пустой стол — ясная голова.", "Мозгу нужно 15 минут, чтобы включиться. Один день — одна тема сильнее, чем по кусочку.", "Развлечения — награда после дела, а не начало дня."], "tasks": [{"t": "Убрать Brawl Stars и ленты с первого экрана телефона", "how": "В папку на последний экран."}, {"t": "24 часа без коротких видео", "how": "Мессенджеры — только по делу."}, {"t": "День погружения: 4–5 часов над треком, телефон в другой комнате", "how": "Как ты и любишь — за один присест."}], "cards": ["12.11", "12.10", "8.3", "1.6", "7.16", "11.17", "11.32", "8.6"]}, {"id": "c9", "st": 2, "p": "head", "t": "Тревога и тоска: тормоза", "why": "Тревога и тоска каждый день — это не характер, а перегретая система. Мозг «разгоняется» и не тормозит. Тормоза тренируются: дыхание, тело, бумага.", "les": ["Когда мыслей слишком много, сложно начать — и тянет в еду, игры, ленту. Это не лень. Лечится дыханием, ходьбой, ручным трудом, холодом.", "Невроз — это отрицание. Признай: «да, мне сейчас тревожно. Ну и что». Половина напряжения уходит.", "Если тоска почти каждый день больше двух недель — это повод сходить к психологу или врачу. Это как стоматолог: сила, а не слабость."], "tasks": [{"t": "7 вечеров: дыхание 4–6 перед сном", "how": "Вдох на 4, выдох на 6, 5 минут."}, {"t": "Один раз при накрутке: лечь на пол, «сегодня я в безопасности»", "how": "Руки под голову, глаза закрыты, медленный выдох."}, {"t": "Неделю: настроение 1–10 перед сном и что помогло", "how": "Через неделю увидишь, что поднимает, а что топит."}], "cards": ["1.5", "1.25", "9.11", "9.15", "7.9", "3.2", "1.29", "11.35", "9.5"]}, {"id": "c10", "st": 2, "p": "head", "t": "Отношение к себе", "why": "«Останусь таким же» — это страх, а не правда. Кто годами ругает себя, тот бьёт брошенного ребёнка. Сила спокойна.", "les": ["Говори с собой, как отец с сыном: что сказал бы ему — то и себе.", "Самооценку поднимают вручную: вспомни свои победы и сравни себя с собой год назад.", "Гнев — запасное топливо: «это чё, всё? Это был весь я?» Используй его в дело, а не в самоедство."], "tasks": [{"t": "Список 10 побед с детства", "how": "Настоящие, без «подумаешь». Музыка, люди, спорт, что угодно."}, {"t": "7 вечеров: одна фраза поддержки себе + победа дня", "how": "В заметку."}, {"t": "Письмо себе через год: кем ты стал", "how": "Свой угол, деньги, микстейп, минус кило. Прочитай, когда опускаются руки."}], "cards": ["1.15", "1.28", "11.31", "1.24", "11.13", "11.14", "1.27", "3.3"]}, {"id": "c11", "st": 2, "p": "body", "t": "Гормональный пульт", "why": "Настроение, воля, смелость, тяга к сладкому — работа гормонов. Ими можно управлять. Мозг замечает перемены через 14–16 дней.", "les": ["5 законов: сначала движение; чувствительность важнее выработки; отдых от стимула; 14–16 дней; к пикам привыкаешь.", "Поза победителя за 2 минуты сдвигает тестостерон и кортизол.", "Тоника — когда тело согласно с тем, что ты задумал. Без неё всё на силе воли, а её мало."], "tasks": [{"t": "Карта гормонов: найти 2–3 проседающих и по рычагу на каждый", "how": "Портреты — в «Знаниях», группа «Гормоны»."}, {"t": "2 минуты позы победителя перед важным звонком", "how": "Грудь раскрыта, подбородок вверх."}, {"t": "14 дней одной привычки (не обязательно подряд)", "how": "Выбери одну из главных 6."}], "cards": ["9.1", "9.2", "9.3", "9.4", "9.8", "9.9", "9.10", "9.12", "9.13", "1.4", "9.14"]}, {"id": "c12", "st": 3, "p": "brave", "t": "Смелость", "why": "Страх людей — натренированная реакция: краснеешь, сохнет горло, горит голова. Это перенастраивается маленькими победами, как отжимания.", "les": ["Опыт — только в попытках. Отказ — это строка «почему / что поменяю», а не провал.", "Мобы своего уровня: не прыгай сразу на босса. Спросить дорогу → заказать голосом → позвонить.", "Противоположность трусости — не брутальность, а радость. Страх смерти — это страх «так и не жил»."], "tasks": [{"t": "10 взглядов в глаза за день", "how": "До конца фразы собеседника."}, {"t": "5 коротких разговоров с незнакомыми за неделю", "how": "Кассир, продавец, прохожий."}, {"t": "Позвонить, а не написать — один раз", "how": "Перед звонком: выдох 4–6, глоток воды."}], "cards": ["1.22", "1.20", "1.21", "3.0", "7.8", "12.21", "1.3", "1.23"]}, {"id": "c13", "st": 3, "p": "brave", "t": "Речь и мысль", "why": "Тяжело формулировать — значит, мысль не упакована. Это навык, а не талант. Люди слушают тех, кто говорит просто и коротко.", "les": ["Говори просто: сложное — простыми словами. Переубеждать бесполезно — показывай себя.", "Пауза звучит увереннее, чем «блин, типа, короче».", "Учишься, когда участвуешь: вопрос → ответ → закрепилось."], "tasks": [{"t": "Объяснить за минуту, как ты делаешь бит", "how": "Запиши голосовое. Как будто объясняешь ребёнку."}, {"t": "Пересказать фильм за 2 минуты: начало → что случилось → чем кончилось", "how": "Запиши и послушай."}, {"t": "Листок «5 тем обо мне»: истории, которые ты можешь рассказать", "how": "Для собеседований и новых людей."}], "cards": ["11.11", "11.18", "12.9", "11.7", "11.6", "12.22"]}, {"id": "c14", "st": 3, "p": "brave", "t": "Границы: добрый, но с зубами", "why": "Ты слишком часто соглашаешься на то, чего не хочешь. Люди — как газ: занимают всё место, которое им дали. Границы — это не злость, а уважение к себе.", "les": ["Агрессия — это не насилие, а занять своё место и сказать прямо. Её выход — через тело.", "Подстройка под всех — начало деградации: мозг учится угадывать, а не расти.", "Решай на своей стороне: не проси мир подстроиться — сделай своё действие."], "tasks": [{"t": "Вместо «да» сказать «мне надо подумать»", "how": "Хотя бы раз."}, {"t": "Отказать без оправданий", "how": "«Не, не могу». Точка."}, {"t": "Разобрать «Броню»: 8 ситуаций манипуляций в «Знаниях»", "how": "Угадай приём, потом открой ответ."}], "cards": ["1.7", "7.2", "7.12", "9.8", "7.14", "7.15", "5.0", "5.1", "5.2", "5.3", "6.0", "6.1", "6.2", "6.3", "6.4", "6.5", "6.6", "6.7"]}, {"id": "c15", "st": 3, "p": "brave", "t": "Люди и окружение", "why": "На кого смотришь — тем становишься. Кроме Эдуарда, почти никого — значит, круг надо строить. Сначала ценность, потом просьба.", "les": ["Разговор начинается с другого: сначала спроси о нём, потом о себе.", "Найди 2–3 «версии себя» — людей, которые уже там, где хочешь быть ты, — и копируй их привычки.", "Благодарность — это дело: не «спасибо», а конкретное действие."], "tasks": [{"t": "День «не о себе»: в каждом разговоре сначала спросить о человеке", "how": "И в переписке тоже."}, {"t": "Поблагодарить родителей конкретно: за что и что это тебе дало", "how": "Не учить и не исправлять — принять."}, {"t": "Найти 3 артистов или людей, которые начинали как ты, и разобрать их путь", "how": "Кай Энджел, Лил Пип — как они начинали? Что делали первый год?"}], "cards": ["12.17", "12.24", "11.29", "1.13", "7.3", "11.23", "1.30", "9.16", "1.14", "8.5", "3.1"]}, {"id": "c16", "st": 4, "p": "music", "t": "Музыка как дело", "why": "У тебя есть идеи, которые могут взлететь. Но миру важны только действия: трек, который не вышел, не существует.", "les": ["Глубинное молчание: не рассказывай о треке, пока он не готов. Рассказ уже даёт мозгу награду — и делать становится не нужно.", "Удача — закономерность: 0,8% действий дают половину результата. Найди свои в музыке и делай каждый день.", "Троечки не существует: трек либо закончен, либо нет. Проигрывай в малом — пиши много плохого, чтобы появилось хорошее."], "tasks": [{"t": "Неделя глубинного молчания про музыку", "how": "Никому не рассказывать, что делаешь. Только показывать готовое."}, {"t": "Найти свои 0,8%: что реально двигает трек вперёд", "how": "Запиши 3 действия и делай их неделю."}, {"t": "Довести один трек до конца — без «потом доделаю»", "how": "Бит, текст, запись, сведение. Пусть не идеально."}], "cards": ["1.2", "12.18", "11.22", "11.21", "12.7", "12.12", "11.26", "1.9", "1.10", "11.36", "7.1"]}, {"id": "c17", "st": 4, "p": "deals", "t": "Работа: первые деньги", "why": "Нужно 50 тысяч в месяц и свои деньги, а не родительские. Первая подработка — не навсегда, а топливо: FL, зал, переезд.", "les": ["Решение — то, что можешь сейчас: не «найти работу», а «5 откликов сегодня».", "30 минут на анализ: резюме, выбор, план — даёшь себе 30 минут и делаешь как есть, пусть криво.", "Решения вероятностны: отказали — это не провал личности, а вероятность. Следующий."], "tasks": [{"t": "Резюме за 30 минут — как есть", "how": "Склад, официант. Не вылизывать."}, {"t": "5 откликов за один присест", "how": "Засчитай сразу."}, {"t": "Перед собеседованием: поза силы 2 минуты и листок «5 тем обо мне»", "how": "Засчитай после собеса."}], "cards": ["11.37", "12.15", "4.0", "3.3", "11.2", "11.3"]}, {"id": "c18", "st": 4, "p": "look", "t": "Образ и подача", "why": "Образ работает, даже когда тебя нет в комнате. Тёмная одежда — твоя база, это нормально. Теперь — сделать её осознанной и добавить своё.", "les": ["Казаться или быть: низкий ранг мечтает казаться, сильный хочет быть. Стиль — это продолжение тебя, а не маска.", "Задор: выбирать хорошее настроение, даже когда всё плохо. Это видно по лицу и походке.", "Ты — это твой обычный день: в чём ходишь, как держишься, как пахнешь."], "tasks": [{"t": "Найти 3 образа на Pinterest, которые нравятся, и понять, что их объединяет", "how": "Силуэт, цвет, детали."}, {"t": "Записать себя на видео 1 минуту и пересмотреть", "how": "Осанка, голос, руки. Одна вещь, которую поменяешь."}, {"t": "Сходить на улицу в новом образе", "how": "Засчитай после."}], "cards": ["11.16", "11.38", "1.16", "11.2", "1.12"]}, {"id": "c19", "st": 4, "p": "deals", "t": "Деньги без хаоса", "why": "Деньги от родителей уходят на проезд и вкусняшки. Сначала видеть деньги, потом управлять ими.", "les": ["Видеть деньги: каждая трата — строкой.", "Одно действие на доход сильнее трёх мелких экономий.", "«Экономлю на потом» — потом не наступает. Копить можно, но на конкретное: FL, зал, свой угол."], "tasks": [{"t": "Записать все траты за 3 дня", "how": "Засчитай на третий день."}, {"t": "Одно действие на доход", "how": "Отклик, разговор о подработке, продажа ненужной вещи."}, {"t": "Отложить первую сумму на конкретную цель", "how": "FL Studio или абонемент."}], "cards": ["11.20", "11.12", "7.13", "1.9"]}, {"id": "c20", "st": 4, "p": "head", "t": "Чего ты хочешь на самом деле", "why": "Через год: свой угол, деньги, минус вес, музыка и аудитория. Проверим, какие из этих «хочу» настоящие — и какую цену ты готов платить.", "les": ["Два «хочу»: по одним делаешь шаги, другие — «не отказался бы». Вторые — не цели.", "Джинн: все хотят похудеть, но не все выбирают похудеть. Выбор — это действия и цена.", "Ты — результат условий. Не ругай клубнику — поменяй почву."], "tasks": [{"t": "Разделить свои «хочу» на настоящие и «не отказался бы»", "how": "Письменно."}, {"t": "Для каждой цели года — цена: что я перестаю делать", "how": "Например, Brawl Stars 2 часа → час на трек."}, {"t": "Поменять одно условие вместо уговоров себя", "how": "Ноут на стол утром, кроссовки у двери, сладкое не покупать."}], "cards": ["7.5", "7.4", "11.15", "12.16", "1.11", "7.7", "12.14", "11.19", "11.34", "7.6", "7.10"]}], "groups": ["Как устроена игра", "Арсен: основа", "Ваагн", "Лимарев", "Resolve", "Тёмная триада", "Броня: угадай приём", "Арсен: разборы I", "Энергия", "Гормоны", "Сон", "Арсен: разборы II", "Арсен: эфиры"], "cards": [{"id": "g.6", "g": "Как устроена игра", "t": "Ранги", "x": "E, D, C, B, A, S. С ранга D открывается ветка «Девушки»."}, {"id": "g.5", "g": "Как устроена игра", "t": "Свиток дня", "x": "Каждый день открывается одна новая карточка из базы. Прочитал — +5 XP. За полгода откроется вся база."}, {"id": "g.4", "g": "Как устроена игра", "t": "Курс", "x": "5 ступеней, 20 тем. Тема открывается, когда закрыты 3 задания прошлой. С каждой темой открываются её карточки знаний."}, {"id": "g.3", "g": "Как устроена игра", "t": "Видишь только следующий шаг", "x": "Как в Skyrim: в квесте виден текущий шаг. Большой план пугает, один шаг — нет."}, {"id": "g.2", "g": "Как устроена игра", "t": "Минимум дня", "x": "Одно любое дело — и день засчитан, серия жива. Пропуск = −30 XP и 30 отжиманий в долг."}, {"id": "g.1", "g": "Как устроена игра", "t": "Опыт только за дело", "x": "Опыт дают только за сделанное. Разговоры, планы и «я бы мог» стоят ноль."}, {"id": "1.0", "g": "Арсен: основа", "t": "Пять путей силы", "x": "Материя, Образы, Ментал, Тело, Социум. Придумал в 15–18 лет как «методы прокачки своего персонажа». Пути можно комбинировать, база — Ментал и Тело."}, {"id": "1.1", "g": "Арсен: основа", "t": "Фарм значимости", "x": "Чувство важности можно добывать делом, а можно словами: спорить, обесценивать, разоблачать, рассказывать о планах. Слова дают ту же награду без усилия — как наркотик. «Приучишь себя добывать значимость словами — не сможешь добывать её действиями».", "fy": "Не спорь в чатах и не доказывай словами — доказывай треками и цифрами в дуэли."}, {"id": "1.2", "g": "Арсен: основа", "t": "Глубинное молчание", "x": "Не рассказывать о планах и изменениях, пока нет результата. Рассказ уже даёт мозгу награду, и делать становится не нужно. Всё лучшее он делал молча.", "fy": "Не рассказывай про альбом, пока он не вышел. Даже Эдуарду — только готовое."}, {"id": "1.3", "g": "Арсен: основа", "t": "Лёгкие соперники", "x": "Чемпиона растят так: сначала подбирают соперников, которых он точно пройдёт, потом сильнее. Так же возвращается доверие к себе: маленькие выполненные цели, одна задача до конца.", "fy": "Поэтому в игре лестницы: сначала спросить дорогу, потом звонок, потом собеседование."}, {"id": "1.4", "g": "Арсен: основа", "t": "Тоника", "x": "Настрой тела под действие: когда внутренняя «горилла» согласна с тем, что ты задумал. Без тоники всё идёт на силе воли и быстро выдыхается. Поэтому внедряем в кайф: например, ходить по дорожке, включив кино, которое хотел посмотреть.", "fy": "Тренируйся под музыку, которую любишь. Тогда тело само согласится."}, {"id": "1.5", "g": "Арсен: основа", "t": "Разгон и торможение", "x": "Когда мыслей слишком много (мало ГАМК), человек не может начать и сливается в еду, игры, сериалы. Это не лень. Лечится дыханием, ходьбой, тупым ручным трудом, холодом, а не кофе.", "fy": "Когда не можешь сесть за трек и залипаешь в Brawl Stars — это оно. 5 минут дыхания или прогулка, потом ноут."}, {"id": "1.6", "g": "Арсен: основа", "t": "Триада биозомби", "x": "Бои, порно, негативные новости. Выжигают дофамин и серотонин, обычная жизнь становится пресной. «Чем больше смотришь новости, тем меньше зарабатываешь».", "fy": "Для тебя «триада» — ленты, Brawl Stars часами и порно. Меньше их — больше желания делать музыку."}, {"id": "1.7", "g": "Арсен: основа", "t": "Принцип агрессии", "x": "Агрессия — экспансия вовне: занять место, благоустроить под себя. Она останавливается только встречной силой. Поэтому границы ставятся сразу, а отношения строятся так, чтобы людям было выгоднее сотрудничать, чем нет."}, {"id": "1.8", "g": "Арсен: основа", "t": "Предельное авторство", "x": "Всё, что происходит в жизни, — следствие моих действий и мыслей. Не поиск виноватых, а вопрос «что я могу сделать?». Так ты максимально обучаем.", "fy": "Военкомат, пробная FL, общий ноут — всё правда. Но вопрос всегда: что я могу сделать сегодня?"}, {"id": "1.9", "g": "Арсен: основа", "t": "Удача — закономерность", "x": "Удача складывается из мелких ежедневных действий в сторону цели. 0,8% действий дают половину результата — найди свои и делай каждый день.", "fy": "В музыке твои 0,8% — это законченные треки, а не новые наброски."}, {"id": "1.10", "g": "Арсен: основа", "t": "Троечки не существует", "x": "В жизни задача либо решена, либо нет. Видимость работы не считается. Поэтому квест засчитывается только по результату.", "fy": "Набросок — не трек. Засчитывается только законченное."}, {"id": "1.11", "g": "Арсен: основа", "t": "Вопрос «Зачем?»", "x": "«Почему» ищет причину, «зачем» — цель. Вопрос «зачем?» ставит на место любую глупость и лишнее дело."}, {"id": "1.12", "g": "Арсен: основа", "t": "Сущее и должное", "x": "Видеть то, что есть, а не то, что хочется видеть. Самая сильная позиция — видеть реальность и связи между вещами."}, {"id": "1.13", "g": "Арсен: основа", "t": "Теплота", "x": "Первый фильтр людей: как человек говорит, двигается, как относится к твоим ошибкам. Будь как радиатор — грей сам, не жди.", "fy": "Тебе это проще всего — ты добрый. Осталось добавить границы."}, {"id": "1.14", "g": "Арсен: основа", "t": "Принятие родителей", "x": "Не учить и не исправлять родителей, а принять: «экспонат в музее — смотреть можно, руками не трогать». Отблагодарить, а не «обеспечить». От этого растёт внутренняя сила.", "fy": "Родители подгоняют — это забота, а не давление. Прими их такими, какие есть."}, {"id": "1.15", "g": "Арсен: основа", "t": "Без самокритики", "x": "Никогда себя не обесценивать. Относиться к себе как к сыну: что сказал бы ему — то и себе. Ошибка — это «нашёл поломку, починил, иду дальше», а не самобичевание.", "fy": "«Останусь долбоёбом» — так ты бы сыну не сказал. Не говори и себе."}, {"id": "1.16", "g": "Арсен: основа", "t": "Задор", "x": "Главный урок воли по Арсену: выбирать хорошее настроение, даже когда всё плохо, и держать курс без подходящих условий.", "fy": "Тоска каждый день — не приговор. Задор тренируется, как отжимания."}, {"id": "1.18", "g": "Арсен: основа", "t": "Не постепенно, а регулярно", "x": "Человек похудел на 68 кг за полгода: каждый день в одно время ходил в зал на 5 минут, пару раз дёргал штангу и уходил. Сначала привычка появляться, потом интенсивность.", "fy": "Зал: сначала просто приходи. Даже 5 минут засчитываются."}, {"id": "1.19", "g": "Арсен: основа", "t": "Делание против результата", "x": "«Хожу в зал 5 лет — почему не накачался? Потому что ты ходишь в зал». Любую задачу формулировать как результат и спрашивать: к какому результату это ведёт, это самый короткий путь?", "fy": "Не «сижу над музыкой», а «закончил трек». Не «хожу в зал», а «минус 3 кг»."}, {"id": "1.20", "g": "Арсен: основа", "t": "Мобы своего уровня", "x": "Мобы на 20 уровней ниже — гарантированная победа и ноль опыта. Своего уровня — хороший опыт и лут. Рейд-босс выше — шанс 1%, но если завалишь… Ищем людей и задачи ниже уровнем из страха отказа.", "fy": "Не начинай с выступления на сцене. Сначала спроси дорогу."}, {"id": "1.21", "g": "Арсен: основа", "t": "Ранг — ощущение «мне можно»", "x": "Ранг — это ощущение внутренней обезьяны, что тебе можно, а что нельзя. Быстрее всего растёт, когда делаешь то, во что искренне не верил, что сможешь. Отсюда ранговые испытания в игре.", "fy": "Ранг растёт, когда делаешь то, во что не верил. Первый звонок незнакомому — уже ранговый шаг."}, {"id": "1.22", "g": "Арсен: основа", "t": "Противоположность трусости — радость", "x": "Не смелость, а жизнелюбие. Качать «серьёзность и брутальность» от трусости — ещё меньше радости. Страх смерти — это страх «так и не жил».", "fy": "Соцфобия лечится не брутальностью, а радостью от маленьких побед."}, {"id": "1.23", "g": "Арсен: основа", "t": "Доверие к себе", "x": "Берёшь дела, которых не хочешь, — начинаешь их саботировать и теряешь доверие к себе. Восстанавливается реалистичными маленькими целями и одной задачей до конца. Чемпиону сначала подбирают соперников, которых он точно пройдёт.", "fy": "Поэтому в игре маленькие шаги и первый шаг жёлтым."}, {"id": "1.24", "g": "Арсен: основа", "t": "Состояние бесплатно", "x": "Смысл достижений — испытать состояние, а оно бесплатно: быть довольным собой и радоваться жизни можно уже сейчас. Достижение с потерей покоя не считается."}, {"id": "1.25", "g": "Арсен: основа", "t": "Сегодня я в безопасности", "x": "При суете: лечь на пол, руки под голову, закрыть глаза и сказать себе «сегодняшний день закончится без происшествий, сегодня я в безопасности». Представить, что мозг охлаждают кулеры.", "fy": "Когда горит голова и сохнет горло — это твоя кнопка."}, {"id": "1.26", "g": "Арсен: основа", "t": "Один на один", "x": "Любое препятствие — это я слабый против меня сильного. Мокрые шнурки, пасмурно, соседка — не оправдания.", "fy": "Ноут общий, дома шумно — ты против себя. Ищешь время, когда никого нет, а не отмазку."}, {"id": "1.27", "g": "Арсен: основа", "t": "Гнев — это дар", "x": "«Это чё, всё? Это был весь я?» Запасное топливо: когда ничто не заводит — вспомнить ситуацию поражения и отказа, пока не появится ответная реакция.", "fy": "Твоё топливо — «никогда не стану тем, кем хочу». Вспоминай это, когда лень, а не когда грустно."}, {"id": "1.28", "g": "Арсен: основа", "t": "Самооценка вручную", "x": "Поднять — вспомнить свои победы и сравнить себя с собой год назад. Опустить (когда зазнался) — сравнить с гигантами.", "fy": "Раз в месяц сравнивай себя с собой прошлым. Вкладка «Дуэль» делает это за тебя."}, {"id": "1.29", "g": "Арсен: основа", "t": "Нейтральность к миру", "x": "Никого не ненавидеть — это слив энергии. Злость на тех, от кого зависишь, тратить на то, чтобы стать сильнее."}, {"id": "1.30", "g": "Арсен: основа", "t": "Зеркальные нейроны", "x": "Окружение, фильмы, книги, музыка героического типа меняют тебя — как сына, смотревшего с отцом Али–Фрейзер. Загружать нужные образы.", "fy": "Слушай и смотри тех, кем хочешь стать. Твои артисты — тоже окружение."}, {"id": "2.0", "g": "Ваагн", "t": "Поднять ил", "x": "Каждое незакрытое дело висит в голове и жрёт энергию фоном (эффект Зейгарник). Поэтому сначала выгружаем всё из головы по 8 блокам вопросов на внешний носитель.", "fy": "Поэтому тебе тяжело начать: голова забита делами, которые нигде не записаны."}, {"id": "2.1", "g": "Ваагн", "t": "Разбор корзины", "x": "Каждую выгруженную мысль прогоняем по вопросам: нужно ли вообще? Сделаю за 2 минуты? Могу поручить? Когда сделаю? Итог: сделать, удалить, поручить, поставить срок или отправить в «Когда-нибудь»."}, {"id": "2.2", "g": "Ваагн", "t": "Одна точка входа", "x": "Всё новое — только во «Входящие» на экране «Сегодня». Голова для идей, а не для хранения."}, {"id": "2.3", "g": "Ваагн", "t": "Маяки", "x": "Один результат на месяц в 2–3 направлениях, заявленный заранее. Здоровье — обязательно. Смысл не в кайфе, а во вкусе личной победы. У тебя это «Цель месяца»."}, {"id": "2.4", "g": "Ваагн", "t": "Буст → инвестиция", "x": "Закрыл дело — появилась энергия. Её сразу вкладываешь в следующий маленький шаг. Так понемногу набирается капитал сил.", "fy": "Отдал 200 брату — сразу следующий шаг. Энергия есть, пока горячо."}, {"id": "2.5", "g": "Ваагн", "t": "Реформу довести до конца", "x": "Самое страшное в начатых изменениях — бросить их на полпути: старое разрушено, новое не собрано. Поэтому тихо, медленно, без очарования."}, {"id": "3.0", "g": "Лимарев", "t": "Прочность", "x": "Прочность — это парашют: если опоры исчезнут, снижаешься плавно. Боимся не проблемы, а давления вокруг неё. Проблема — ветер, ты — парус. Каждый день одно «зелёное» действие из списка «хочу, но боюсь».", "fy": "«Хочу, но боюсь» — твой список: позвонить, собеседование, показать трек."}, {"id": "3.1", "g": "Лимарев", "t": "Версии себя", "x": "Около 27 млн людей с психикой как у тебя. Найди 2–3, которые уже там, где ты хочешь быть, и копируй их мышление, привычки, распорядок. Сначала «спиши» результат, потом шлифуй своё.", "fy": "Найди 2–3 артиста, которые начинали из комнаты с ноутом. Копируй их первый год."}, {"id": "3.2", "g": "Лимарев", "t": "Менеджмент состояния", "x": "Состояние — фильтр восприятия: от него реакции, события, изменения. Его можно создавать изнутри, а не ждать достижений."}, {"id": "3.3", "g": "Лимарев", "t": "Решения вероятностны", "x": "Мы решаем на крохах данных и не можем требовать от себя гарантий. Не сработало — это не провал личности, а вероятность."}, {"id": "4.0", "g": "Resolve", "t": "30 минут на анализ", "x": "Когда долго думаешь над решением (резюме, выбор, план) — даёшь себе 30 минут, потом делаешь как есть, пусть криво. Против «ловушки интеллекта» и «80–90% знаний не внедряю».", "fy": "Резюме, обложка, выбор работы — 30 минут, и делаешь как есть."}, {"id": "4.1", "g": "Resolve", "t": "Датчик усталости 1–4", "x": "Раз в неделю, в воскресенье: на каком я уровне усталости? 1 — всё как обычно; 2 — новых привычек не брать; 3 — только сон, еда, прогулка; 4 — только врач и отдых."}, {"id": "5.0", "g": "Тёмная триада", "t": "Три черты", "x": "Нарциссизм — жажда восхищения и непереносимость критики. Макиавеллизм — холодный расчёт, люди как ресурс. Психопатия — мало сочувствия, нет вины, импульсивность. Это черты, не диагнозы; опасно, когда сильные и вместе.", "fy": "Тебе нужна здоровая доза: спокойная самоценность, расчёт, холодная голова. Без вреда людям."}, {"id": "5.1", "g": "Тёмная триада", "t": "Судить по поступкам", "x": "Смотри, что человек делает за время, а не что говорит. Сигнал: после общения ты слабее, должен и сомневаешься в себе."}, {"id": "5.2", "g": "Тёмная триада", "t": "Приём → ответ", "x": "Срочность → «отвечу завтра». Газлайтинг → «давай запишу». Вина → «есть реальная причина?». Давление → «туман» или «заезженная пластинка». Эмоции → пауза 6 секунд. Игнор как наказание → не бежать."}, {"id": "5.3", "g": "Тёмная триада", "t": "Торг", "x": "Назови цифру первым (верх вилки), после — молчи. «Надо сегодня» → «мне нужны сутки». Торгуются не только деньги. Итог — письменно."}, {"id": "6.0", "g": "Броня: угадай приём", "t": "Ситуация 1", "x": "Знакомый хвалит тебя при всех, а наедине говорит, что без него у тебя ничего не выйдет.", "a": "Макиавеллизм: разным людям — разные версии."}, {"id": "6.1", "g": "Броня: угадай приём", "t": "Ситуация 2", "x": "Новый знакомый через час называет вас родственными душами и просит в долг", "a": "Психопатия и лавбомбинг: быстрая близость + просьба."}, {"id": "6.2", "g": "Броня: угадай приём", "t": "Ситуация 3", "x": "Работодатель: «Выходи завтра, ответ нужен прямо сейчас».", "a": "Срочность. Ответ: «Мне нужны сутки»."}, {"id": "6.3", "g": "Броня: угадай приём", "t": "Ситуация 4", "x": "Друг на мягкое замечание обижается и неделю не отвечает.", "a": "Нарциссическая реакция + молчаливое наказание."}, {"id": "6.4", "g": "Броня: угадай приём", "t": "Ситуация 5", "x": "«Я такого не говорил, тебе показалось» — а переписка есть", "a": "Газлайтинг. Ответ: фиксировать письменно."}, {"id": "6.5", "g": "Броня: угадай приём", "t": "Ситуация 6", "x": "«После всего, что я для тебя сделал…»", "a": "Вина как рычаг. Вопрос: есть реальная причина или только давление?"}, {"id": "6.6", "g": "Броня: угадай приём", "t": "Ситуация 7", "x": "«Вот Саша бы уже давно сделал»", "a": "Триангуляция — сравнение с третьим."}, {"id": "6.7", "g": "Броня: угадай приём", "t": "Ситуация 8", "x": "Человека поймали на вранье, а он улыбается и продолжает как ни в чём не бывало", "a": "Психопатия: нет чувства вины."}, {"id": "7.0", "g": "Арсен: разборы I", "t": "Психософия: 4 функции × 4 позиции", "x": "Логика, воля, физика, эмоция — у каждого в своём порядке. Первую функцию не переубеждают, третью (больную) человек прячет или выпячивает."}, {"id": "7.1", "g": "Арсен: разборы I", "t": "Продажа = мнение", "x": "Продают не товар, а мнение о нём. Предпринимательство — видеть несоответствие и закрывать его. Мелочей нет."}, {"id": "7.2", "g": "Арсен: разборы I", "t": "Агрессия ≠ насилие", "x": "Агрессия — это экспансия: занять своё место, сказать прямо. Насилие — когда ломаешь другого. Выход агрессии — через тело.", "fy": "Злость — не плохо. Направь её в зал и в музыку."}, {"id": "7.3", "g": "Арсен: разборы I", "t": "Окружение подтверждает самооценку", "x": "Кто рядом с тобой, тот подтверждает, какой ты. Если рядом те, кто считает тебя слабым, — это их подтверждение каждый день.", "fy": "Рядом с Эдуардом ты растёшь — держи это. Ищи ещё таких."}, {"id": "7.4", "g": "Арсен: разборы I", "t": "Я для этого или это для меня?", "x": "Проверка работы, отношений и привычек: я служу этому или это служит мне?"}, {"id": "7.5", "g": "Арсен: разборы I", "t": "Два хочу", "x": "«Хочу» бывает двух видов: делаю шаги — или просто не отказался бы. Вторые цели — не цели.", "fy": "Свой угол, деньги, музыка — проверь, по каким ты реально делаешь шаги."}, {"id": "7.6", "g": "Арсен: разборы I", "t": "Самооценка раньше способностей", "x": "Сначала честная самооценка, потом рост способностей. Не наоборот."}, {"id": "7.7", "g": "Арсен: разборы I", "t": "Ты — результат условий", "x": "Не ругай клубнику — поменяй почву. Не бороться с условиями, а менять их."}, {"id": "7.8", "g": "Арсен: разборы I", "t": "Отказ = форма B", "x": "Каждый отказ — одна строка «почему / что поменяю». Тогда отказ даёт очки, а не только боль.", "fy": "Отказ на собеседовании или от девушки = одна строка «почему / что поменяю»."}, {"id": "7.9", "g": "Арсен: разборы I", "t": "Невроз = отрицание", "x": "Лечение — «да, так. Ну и что». Признание снимает половину напряжения."}, {"id": "7.10", "g": "Арсен: разборы I", "t": "Радость — настояться, печаль — поделиться", "x": "Хорошее сначала переживи сам и запиши. Делись с тем, кто порадуется сильнее тебя. Фильтр: «это помогает делу?»"}, {"id": "7.11", "g": "Арсен: разборы I", "t": "Мир должен", "x": "«Меня должны уважать» → «каким мне стать, чтобы уважали?». «Меня перебивают» → «я говорю нудно, высокомерно или не тем подходом?»."}, {"id": "7.12", "g": "Арсен: разборы I", "t": "Люди — газ", "x": "Люди занимают всё пространство, которое им даёшь. Дал в долг без условий — не удивляйся.", "fy": "Соглашаешься на то, чего не хочешь, — люди займут всё твоё время."}, {"id": "7.13", "g": "Арсен: разборы I", "t": "Мелочи как бегство от выбора", "x": "Бытовые мелочи и долги часто прячут главный выбор. Страх выбора мумифицирует жизнь."}, {"id": "7.14", "g": "Арсен: разборы I", "t": "Казаться или быть", "x": "Подстройка под всех — начало деградации: мозг учится угадывать, а не расти. Ценный совет не требует менять себя."}, {"id": "7.15", "g": "Арсен: разборы I", "t": "Решай на своей стороне", "x": "Не проси мир подстроиться — сделай своё действие: беззвучный режим, отписка, уйти раньше."}, {"id": "7.16", "g": "Арсен: разборы I", "t": "Отдых — после дела", "x": "Развлечения — награда за закрытый блок, а не начало дня.", "fy": "Brawl Stars и FIFA — после трека, а не вместо."}, {"id": "7.17", "g": "Арсен: разборы I", "t": "Добавки — только после анализов", "x": "Добавка — прицел на винтовку: без сна, еды и нагрузки не работает. Любые добавки — после анализов и разговора с врачом."}, {"id": "8.0", "g": "Энергия", "t": "Мозг не отличает картинку от жизни", "x": "Фантазия запускает настоящие гормоны — как фильм ужасов пугает по-настоящему. Можно выгореть от того, чего нет."}, {"id": "8.1", "g": "Энергия", "t": "Среда, которой не было", "x": "За вечер в сети видишь больше обнажённых тел, чем дед за всю жизнь. Реклама, клипы, фото усиливают стимулы в разы, а тормозов на это природа не дала."}, {"id": "8.2", "g": "Энергия", "t": "Результат минус усилия", "x": "Мозг выбирает дело по формуле «награда минус усилия». Лёгкий кайф выигрывает у любого настоящего дела — если его не убрать.", "fy": "И сладкое, и ленты, и порно — всё это «награда без усилий»."}, {"id": "8.3", "g": "Энергия", "t": "Инфляция счастья", "x": "После пиков простое теряет вкус. Жизнь блекнет не от возраста, а от перегрузки центра удовольствия."}, {"id": "8.4", "g": "Энергия", "t": "Кайф стирает уроки", "x": "Если каждое поражение заливать лёгким удовольствием, мозг не запоминает ошибку и повторяет её по кругу."}, {"id": "8.5", "g": "Энергия", "t": "Социум первым", "x": "Порядок выхода: социум → психика → тело. Надо знать, зачем ты нужен людям. Одиночество толкает в любой побег: игры, сериалы, порно.", "fy": "Одиночество толкает в побег. Строить круг — тоже часть энергии."}, {"id": "8.6", "g": "Энергия", "t": "Сначала кайф, потом развитие", "x": "Окружение должно быть в кайф — иначе сорвёшься. Кайф без развития — пустота."}, {"id": "8.7", "g": "Энергия", "t": "Запрет овладевает тобой", "x": "Блокировщики учат избегать, а нужно научиться правильно реагировать. Работает осознанность, а не запрет."}, {"id": "8.8", "g": "Энергия", "t": "Воздержание без движения не работает", "x": "Энергия растёт, а куда её деть — непонятно, и мозг ведёт по старой дороге. Её надо сразу направлять в тело и новое дело.", "fy": "Энергию сразу — в зал, в отжимания, в трек."}, {"id": "8.9", "g": "Энергия", "t": "Норадреналин — только в действии", "x": "Его нельзя получить лёжа — только идя на ринг, в атаку, на вызов. Топливо — злость на своё положение. Не прятать её за кайфом.", "fy": "Злость на своё положение — топливо. Не заливай её Brawl Stars."}, {"id": "8.10", "g": "Энергия", "t": "Что возвращается", "x": "Меньше пролактина и тревоги, чувствительнее дофамин, сильнее норадреналин: прямая осанка, горящие глаза, легче общаться, доводишь дела до конца."}, {"id": "8.11", "g": "Энергия", "t": "Еда против лишнего эстрадиола", "x": "Не пить из пластика, есть капусту в любом виде, пить цитрусовый сок, снижать жир — в жире тестостерон превращается в эстрадиол."}, {"id": "9.0", "g": "Гормоны", "t": "Закон 1: сначала движение на ногах", "x": "Гормоны доходят до цели только с кровью и лимфой. Минимум — 6–10 км ходьбы и 50–100 приседаний в день; для больших перемен — 10–20 км бега и 400–600 приседаний.", "fy": "Вес и энергия — сначала ноги: шаги и приседания каждый день."}, {"id": "9.1", "g": "Гормоны", "t": "Закон 2–3: чувствительность важнее выработки", "x": "Постоянные пики снижают чувствительность рецепторов. Она возвращается только долгим отдыхом от стимула."}, {"id": "9.2", "g": "Гормоны", "t": "Закон 4: 14–16 дней", "x": "Меньше двух недель мозг считает случайностью. Новая привычка начинает менять тело после 14–16 дней подряд."}, {"id": "9.3", "g": "Гормоны", "t": "Закон 5: к пикам привыкаешь, отвыкать тяжело", "x": "Неестественные всплески становятся нормой, а обычный фон — «мало». Сломать легко, восстанавливаться — долго."}, {"id": "9.4", "g": "Гормоны", "t": "Тестостерон", "x": "Спокойная уверенность, хорошее настроение, «увидел — сделал». Растёт в коридоре борьбы: трудно, но победа возможна. Рычаги: сон, воздержание, много движения, победы, поза победителя, фокус на своём. Низкий: вялость, робость, «само рассосётся».", "fy": "Победы, сон, движение, воздержание — всё это есть в твоих делах дня."}, {"id": "9.5", "g": "Гормоны", "t": "Кортизол", "x": "Допинг за счёт себя, когда ресурсов не хватает. Высокий: всё бесит, ждёшь, что будет, вместо того чтобы действовать. Рычаги: сон, движение, жевание, «я выживал и в худшем», сильное окружение. Бесит всё — решения отложить.", "fy": "Если всё бесит — не принимай решений, сначала прогулка и сон."}, {"id": "9.6", "g": "Гормоны", "t": "Серотонин", "x": "Тихая радость, «завтра будет лучше», сила отказаться от вредного. Рычаги: утреннее солнце, здоровый кишечник, яркие цвета, мир нейтрален — не враждовать с тем, что не вредит, много общения. Сериалы, алкоголь, обжорство его сбивают.", "fy": "Утреннее солнце и меньше сериалов — твой рецепт от тоски."}, {"id": "9.7", "g": "Гормоны", "t": "Мелатонин", "x": "Гормон отдыха и восстановления. Делается из дневного серотонина. Рычаги: после обеда без лишних возбудителей, тёплый свет, длинный выдох, тревоги на бумагу, приватная спальня."}, {"id": "9.8", "g": "Гормоны", "t": "Пролактин", "x": "Режим «отдать всё, лишь бы не спорить». Высокий: тряпка, вина на себе, страх риска. Рычаги: воздержание, сон, не вестись на «пожалейку», среда серьёзных ответственных мужчин.", "fy": "Когда соглашаешься на то, чего не хочешь, — это высокий пролактин. Рычаг — воздержание и сон."}, {"id": "9.9", "g": "Гормоны", "t": "Эстрадиол", "x": "Сила эмоционального взрыва. Высокий: психованность, отёчность, обиды. Рычаги: капуста, лимонный сок, лён, цинк, меньше жира, не пить из пластика, давать эмоциям выход — петь, танцевать, плакать; быть там, где можно быть собой."}, {"id": "9.10", "g": "Гормоны", "t": "Окситоцин", "x": "Чувство «мы одно целое» с близкими, главный антистресс. Рычаги: прикосновения, взгляд в глаза, делиться переживаниями, углублять ближний круг."}, {"id": "9.11", "g": "Гормоны", "t": "Адреналин", "x": "«Беги от» без направления: тревога, дёрганность. Рычаги: движение, где картинка меняется (улица, вело), дать телу подрожать, спросить «где опасность?», убрать уведомления и звук телефона.", "fy": "Перед звонком и собесом — короткая прогулка и долгий выдох."}, {"id": "9.12", "g": "Гормоны", "t": "Норадреналин", "x": "Охота и фокус: спокойствие, поток, азарт, «бей». Рычаги: меньше кофе и громкой музыки, тренировать долгую концентрацию, держать адреналин низким, вернуть себе право защищать границы: «Я могу. Я достоин. Я хочу. Я беру. Я делаю»."}, {"id": "9.13", "g": "Гормоны", "t": "Дофамин", "x": "Любопытство и драйв к новому. Низкий: живёшь от всплеска до всплеска в телефоне. Рычаги: начать с микродвижений пальцев и кистей, потом прогулка; убрать пассивный будоражащий контент; развлекать себя действием; достижения среди людей.", "fy": "Живёшь от всплеска до всплеска в телефоне — это низкий дофамин. Начни с рук: биты, пальцы по клавишам."}, {"id": "9.14", "g": "Гормоны", "t": "Мозг не отличает картинку от жизни", "x": "Фильм ужасов пугает по-настоящему, хотя знаешь, что это кино. Понимать мало — управлять можно только через ощущения."}, {"id": "9.15", "g": "Гормоны", "t": "Реакцию не душить — дать ей пройти", "x": "Запущенную реакцию почти невозможно остановить. Лучше дать ей отработать вхолостую, а потом разобрать, как в неё попал."}, {"id": "9.16", "g": "Гормоны", "t": "На кого смотришь — тем и становишься", "x": "Зеркальные нейроны перестраивают тебя под того, за кем долго наблюдаешь. Выбирай, на кого смотреть."}, {"id": "10.0", "g": "Сон", "t": "Что ломает сон", "x": "Дневной шум и мало движения оставляют адреналин до ночи. Холодный свет и фары глушат мелатонин. Однообразный день тянет «развлечь себя» перед сном. Мало движения — мало аденозина, вещества усталости."}, {"id": "10.1", "g": "Сон", "t": "Три пары на день и ночь", "x": "Утром — кортизол и тестостерон, вечером — аденозин и пролактин. Днём потратить адреналин движением — вечером включится торможение (ГАМК)."}, {"id": "10.2", "g": "Сон", "t": "Норма сна", "x": "Упал — не помнишь, как заснул — проснулся, как после двух чашек кофе. Разбитость по утрам — не норма."}, {"id": "10.3", "g": "Сон", "t": "Первые 15 минут утра", "x": "Настрой на весь день: благодарность, «со всем справлюсь», одно приятное дело первым. Встать раньше всех — меньше давления толпы.", "fy": "Первые 15 минут — без телефона. Ты и так не берёшь его в кровать — продолжай утром."}, {"id": "10.4", "g": "Сон", "t": "Уснуть — значит остыть", "x": "Горячий душ или тренировка, потом остывание — сонливость. Спать без еды, в свежем воздухе, при тёплом свете, в тишине."}, {"id": "10.5", "g": "Сон", "t": "Мелатонин в таблетках вредит", "x": "Огромные дозы глушат свой мелатонин и держат пролактин высоким. Добавки для сна — только через врача."}, {"id": "11.0", "g": "Арсен: разборы II", "t": "Борьба с условиями отнимает силы их изменить", "x": "Силы, уходящие на борьбу с последствиями, выгоднее направить на смену условий. Тактика без стратегии — суета перед поражением.", "fy": "Не воюй с военкоматом — сделай, что можешь, и звони регулярно."}, {"id": "11.1", "g": "Арсен: разборы II", "t": "Выходить на пике удовольствия", "x": "Мозг запоминает последнее впечатление. Бросил на пике — захочется снова; довёл до «заебался» — появится отвращение."}, {"id": "11.2", "g": "Арсен: разборы II", "t": "Потенциал — не ты", "x": "Ты — это твой обычный день: деньги, еда, одежда, где живёшь. Натянутая стрела, которую не выпустил, ничего не стоит.", "fy": "Ты — это не «гениальные идеи», а сколько треков вышло."}, {"id": "11.3", "g": "Арсен: разборы II", "t": "Результат обнуляет усталость", "x": "Засчитанная победа снимает тяжесть процесса. Поражений нет — есть опыт."}, {"id": "11.4", "g": "Арсен: разборы II", "t": "Две правды: закон и эффективность", "x": "По закону виноват вор, но чтобы не крали — закрывай окна. Общество не перевоспитаешь — подстрой стратегию."}, {"id": "11.5", "g": "Арсен: разборы II", "t": "Не понимают — значит, я плохо объяснил", "x": "Взрослый подход. Жертва перекладывает вину на других."}, {"id": "11.6", "g": "Арсен: разборы II", "t": "Любовь без дела не слышна", "x": "Сосна, упавшая на пустой планете, звука не издаёт. Важно, что человек получил, а не что ты чувствовал."}, {"id": "11.7", "g": "Арсен: разборы II", "t": "Учишься, когда участвуешь", "x": "Вопрос → ответ → информация закрепляется. Запись «посмотрю потом» почти не работает. Единственный природный способ учиться — игра.", "fy": "Поэтому знания в игре идут вместе с заданиями."}, {"id": "11.8", "g": "Арсен: разборы II", "t": "Лекарство от зависти — сделай лучше", "x": "Человек тебе не вредит, а бесит — это зависть. Чаще всего завидуем чужой свободе."}, {"id": "11.9", "g": "Арсен: разборы II", "t": "Нежелание — сигнал, а не лень", "x": "Заставил себя — выиграл тактически, проиграл стратегически: в следующий раз слабость от одной мысли.", "fy": "Не хочется садиться за трек — спроси, что не так: время, шум, программа? Поменяй условие."}, {"id": "11.10", "g": "Арсен: разборы II", "t": "Гений входит и выходит сам", "x": "Изменённое состояние («я всё могу») — инструмент, если ты им управляешь, а не оно тобой."}, {"id": "11.11", "g": "Арсен: разборы II", "t": "Сложное — просто", "x": "Люди слушают тех, кто объясняет сложное просто и интересно. Переубеждать бесполезно — показывай себя."}, {"id": "11.12", "g": "Арсен: разборы II", "t": "Пользоваться — тоже навык", "x": "Копить возможности и не пользоваться ими — привычка дефицита.", "fy": "Есть ноут и FL — пользуйся сегодня, а не когда будет идеально."}, {"id": "11.13", "g": "Арсен: разборы II", "t": "Не отматывать прошлое", "x": "Жить попытками исправить сделанное — топтаться на месте. Признать и идти дальше."}, {"id": "11.14", "g": "Арсен: разборы II", "t": "Признать ≠ потворствовать", "x": "«Да, это было, это был я, больше так не сделаю». То, что отрицаешь в себе, прорывается сильнее."}, {"id": "11.15", "g": "Арсен: разборы II", "t": "Джинн — выбор без жертвы", "x": "Настоящий выбор — это действия и цена. Все хотят похудеть, но не все выбирают похудеть.", "fy": "Похудеть выбирают, когда платят цену: меньше сладкого, больше зала."}, {"id": "11.16", "g": "Арсен: разборы II", "t": "Казаться или быть", "x": "Низкий ранг мечтает казаться — одежда, машины, регалии. Сильный хочет быть."}, {"id": "11.17", "g": "Арсен: разборы II", "t": "Погружение, а не нарезка", "x": "Мозгу нужно 15 минут, чтобы включиться. Один день — одна тема сильнее сорока минут по кусочку.", "fy": "Тебе подходит: один длинный присест на 4–5 часов сильнее, чем по 20 минут."}, {"id": "11.18", "g": "Арсен: разборы II", "t": "Совет без «как» пуст", "x": "Все знают, что полезно и что вредно. Ценность — в инструменте."}, {"id": "11.19", "g": "Арсен: разборы II", "t": "Не бойся, если ты один, — бойся, если ты ноль", "x": "Лидера выбирают люди сами. Себя не меняют — создают нового."}, {"id": "11.20", "g": "Арсен: разборы II", "t": "Экономлю на потом — потом не наступит", "x": "Фильтр: буду ли доволен этим решением в конце жизни? Реализованный потенциал дороже накопленного.", "fy": "Копи не «на потом», а на конкретное: FL, зал, свой угол."}, {"id": "11.21", "g": "Арсен: разборы II", "t": "Работа или дело", "x": "Если удивляешься, что тебе за это ещё и платят, — ты на своём месте."}, {"id": "11.22", "g": "Арсен: разборы II", "t": "Любимое на 60% выгоднее нелюбимого на 100%", "x": "Любимое не бросаешь, мастерство растёт от повторений — и деньги приходят.", "fy": "Музыка — любимое. Даже если сначала денег меньше, ты не бросишь."}, {"id": "11.23", "g": "Арсен: разборы II", "t": "Мнение без ответственности — шум", "x": "Слушать тех, кто заинтересован в твоём результате: ошибся — у них проблемы, прав — награда."}, {"id": "11.24", "g": "Арсен: разборы II", "t": "Жалость к себе — низшая просьба", "x": "«Дайте, потому что я убогий». Путь взрослого — равный обмен: сначала дай, потом проси."}, {"id": "11.25", "g": "Арсен: разборы II", "t": "Нет полезного и вредного — есть мера", "x": "У любого параметра есть значение, при котором система работает лучше всего. Правильный вопрос: кто я + задача + что меняю."}, {"id": "11.26", "g": "Арсен: разборы II", "t": "Удовольствие — от того, что получается", "x": "Счастье — это способ жить, а не финиш. Найди ключевой ресурс и сделай его полезным людям.", "fy": "Твой ключевой ресурс — идеи и тексты. Сделай их слышными людям."}, {"id": "11.27", "g": "Арсен: разборы II", "t": "Если надо чинить — не надо чинить", "x": "Кроме себя. Начни выбрасывать с вещей — сдвинется и в голове."}, {"id": "11.28", "g": "Арсен: разборы II", "t": "Мотивация — из детского одобрения", "x": "До 7 лет — бессознательные стремления, до 14 — осознанные."}, {"id": "11.29", "g": "Арсен: разборы II", "t": "Благодарность = дело", "x": "«Ты помог» + «я благодарен» = действие: отзыв, рекомендация, помощь."}, {"id": "11.30", "g": "Арсен: разборы II", "t": "Картина мира рождается из решений", "x": "Сделал → получилось или нет → вывод. Живёшь не чтобы учиться, а чтобы делать. Держи мало источников."}, {"id": "11.31", "g": "Арсен: разборы II", "t": "Доволен — недоволен — маленькие победы", "x": "Глубоко внутри доволен собой, сознательно — ставлю планку выше, каждый день засчитываю маленькие победы.", "fy": "Доволен собой внутри + планка выше + маленькие победы каждый день = твоя игра."}, {"id": "11.32", "g": "Арсен: разборы II", "t": "Миру важны только действия", "x": "Ему всё равно на идеи, мечты и оправдания. Перед длинным видео спроси: что изменится в моей жизни?"}, {"id": "11.33", "g": "Арсен: разборы II", "t": "Кортизол — главный вредитель здоровья", "x": "«Правильное» питание через силу вредит сильнее, чем неидеальное с удовольствием. «Генетика» — отговорка ленивого ума.", "fy": "Не сиди на жёсткой диете. Убери лишнее сладкое — уже минус."}, {"id": "11.34", "g": "Арсен: разборы II", "t": "Копировать не путь, а принятие себя", "x": "У успешных перенимай не книги и рацион, а то, как они приняли себя и развивают свои сильные стороны."}, {"id": "11.35", "g": "Арсен: разборы II", "t": "Сила спокойна", "x": "Настоящая сила спокойна и уверенна. Лишняя агрессия и тревога сообщают, что ты ранен. У сильного нет виноватых."}, {"id": "11.36", "g": "Арсен: разборы II", "t": "Продажа — соблазнение", "x": "Не «додавить», а сделать так, чтобы захотели. В музыке так же: слушателя не уговаривают — его цепляют первыми 10 секундами. Плохой первый контакт убивает даже хороший трек."}, {"id": "11.37", "g": "Арсен: разборы II", "t": "Хорошие мысли — в хорошем качестве", "x": "Иначе стоишь в лохмотьях и удивляешься, почему не признают с порога. Главная проблема хорошего дела — организация.", "fy": "Хорошие идеи в треке — в хорошем качестве: сведение решает."}, {"id": "11.38", "g": "Арсен: разборы II", "t": "Регалии вместо дела", "x": "Чем больше психике нужно ярлыков, тем меньше за ней дела. Объясняешься перед каждым — отстаёшь от себя."}, {"id": "12.0", "g": "Арсен: эфиры", "t": "Жизнь как квест без давления", "x": "Арсен: если бы задания в жизни подавались как квесты в игре — древо заданий, никто не подгоняет, — он бы «играл свою жизнь». Трудолюбие через силу он называл вредным.", "fy": "Ровно то, что делает эта игра."}, {"id": "12.1", "g": "Арсен: эфиры", "t": "Внедряется только любимое", "x": "Через силу через 5–6 недель мозг записывает «это плохо». Метод: месяц понемногу в удовольствие → проверка → шаг вверх. «Обязательство убивает любовь»."}, {"id": "12.2", "g": "Арсен: эфиры", "t": "Договорись, а не дави", "x": "Заставил себя — сегодня победил, но в следующий раз мозг даст ещё меньше энергии. Ищи оттенки желания: короче, по-своему, с наградой сразу после."}, {"id": "12.3", "g": "Арсен: эфиры", "t": "Засчитай победу", "x": "Одно и то же событие можно засчитать как победу или как поражение. Вышел, хоть и не хотел, — победа. Отсюда минимум дня.", "fy": "Отсюда «минимум дня»: одно дело — и день засчитан."}, {"id": "12.4", "g": "Арсен: эфиры", "t": "Экстра-дневник", "x": "Сделанное сверх плана записывай отдельно, как бонус. 50 «экстра» за две недели очень цепляют."}, {"id": "12.5", "g": "Арсен: эфиры", "t": "Результат — сразу", "x": "Горький процесс подслащивают «пилюлей результата», которая приходит немедленно, — так отец Ломаченко растил чемпиона. Поэтому опыт и золото в игре даются сразу."}, {"id": "12.6", "g": "Арсен: эфиры", "t": "Посильная победа", "x": "Тестостерон — гормон преодоления посильного. Не «200 кг и каждый день “я чмо”», не «поднять бутылку», а 45 кг → поднял 47 — и гордишься.", "fy": "Отжимания: 15 → 17 — уже победа. Не сравнивай себя с качками."}, {"id": "12.7", "g": "Арсен: эфиры", "t": "Охота, а не зарплата", "x": "Большой результат приходит рывком: след, берлога, засада — и гора мяса разом. Равномерный ежедневный результат — признак посредственности. Не грызи себя, что прогресса не видно каждый день.", "fy": "Если прогресса не видно каждый день — нормально. Альбом выйдет рывком."}, {"id": "12.8", "g": "Арсен: эфиры", "t": "5 форм власти = 5 путей", "x": "Физическая, интеллектуальная, финансовая, харизма, внешность. В игре это Тело, Ментал, Материя, Социум, Образы — развивать все пять."}, {"id": "12.9", "g": "Арсен: эфиры", "t": "Иллюзия знания", "x": "Услышал за 15 минут — ещё не знаешь. Носителем знания становишься через ~2 года практики. Поэтому — глубинное молчание.", "fy": "Прочитал карточку — ещё не знаешь. Знаешь, когда сделал задание."}, {"id": "12.10", "g": "Арсен: эфиры", "t": "Сначала подумай сам", "x": "Мгновенный ответ лишает навыка находить ответы — так растёт выученная беспомощность. Сначала своя версия, потом поиск."}, {"id": "12.11", "g": "Арсен: эфиры", "t": "Разгрузить оперативку", "x": "Чем больше предметов на виду, тем сильнее распыляется внимание. Убрал всё со столов в шкафы — фокус вырос многократно.", "fy": "Перед музыкой — убери со стола всё лишнее."}, {"id": "12.12", "g": "Арсен: эфиры", "t": "Белый пояс", "x": "Мастер кёкушина пришёл в кудо в чёрном поясе и проиграл, а на следующую тренировку надел белый. Старый опыт мешает в новом деле.", "fy": "В FL и в зале ты новичок — надевай белый пояс и учись без гордости."}, {"id": "12.13", "g": "Арсен: эфиры", "t": "Ты = что делаешь по факту", "x": "Ты — не то, что можешь, а то, что по факту есть: где живёшь, что ешь, сколько зарабатываешь."}, {"id": "12.14", "g": "Арсен: эфиры", "t": "Меняй слагаемые", "x": "Хочешь другой результат — меняй условия, а не уговаривай. Спортшкола во дворе вместо агитации за спорт."}, {"id": "12.15", "g": "Арсен: эфиры", "t": "Решение — то, что можешь сейчас", "x": "«Новая работа» или «новая жизнь» — не решение. Решение — шаг, который можно сделать прямо сейчас.", "fy": "Не «стать артистом», а «сегодня 8 тактов»."}, {"id": "12.16", "g": "Арсен: эфиры", "t": "Зачем, а не как", "x": "Самосаботаж — это фокус на объёме работы («2–3 месяца каждый день»). Правильный вопрос — «зачем мне это?»"}, {"id": "12.17", "g": "Арсен: эфиры", "t": "Сначала ценность, потом просьба", "x": "Люди пишут только о себе, без «здравствуйте». Создай человеку ценность — и он захочет отдать свою."}, {"id": "12.18", "g": "Арсен: эфиры", "t": "Хвастовство съедает цель", "x": "Рассказал о цели или успехе заранее — подал это как гарантию, и прогресс встал.", "fy": "Не рассказывай всем про альбом до релиза."}, {"id": "12.19", "g": "Арсен: эфиры", "t": "Не считать дни воздержания", "x": "Счётчик дней сам задаёт мысль, что это когда-то кончится: «сколько можно?». Поэтому в игре чистые дни не считаются подряд.", "fy": "Поэтому в игре дни без порно не считаются подряд."}, {"id": "12.20", "g": "Арсен: эфиры", "t": "Холод: 5–10 секунд достаточно", "x": "Холодный душ 5–10 секунд даёт главную пользу. Чем экстремальнее практика, тем хуже она закрепляется. «Сперва страшно — потом хорошо»."}, {"id": "12.21", "g": "Арсен: эфиры", "t": "Проигрывай в малом", "x": "На тренировке работай там, где слаб, и проигрывай тысячу раз — победишь в большом. Кто тренирует только то, что получается, встаёт.", "fy": "Пиши много плохих битов. Из сотого получится хороший."}, {"id": "12.22", "g": "Арсен: эфиры", "t": "Учись через нужду", "x": "Сначала спарринг — потом сами захотят разминку. Когда приходит момент, учишься очень быстро."}, {"id": "12.23", "g": "Арсен: эфиры", "t": "Костыль мотивации", "x": "Внешняя мотивация — палка при реабилитации. Вовремя её брось, иначе привыкнешь к инвалидности. Игра — костыль, пока свои привычки не встанут.", "fy": "Игра — костыль, пока свои привычки не встанут. Потом бросишь, и это будет победа."}, {"id": "12.24", "g": "Арсен: эфиры", "t": "Предписание на миллиард", "x": "Найди, на что опираешься как на должное, — отблагодари и отдай должное, иначе исчезнет."}]};
